import { useState, useEffect } from "react";
import { getTransactions, deleteTransaction, createTransaction } from "../services/api";
import { G } from "../App";

const CATEGORIES = ["Food","Transport","Shopping","Health","Entertainment","Utilities","Other"];
const CAT_COLORS = { Food:"#00d4ff", Transport:"#7c3aed", Shopping:"#ff4d6d", Health:"#00ff9d", Entertainment:"#ffd60a", Utilities:"#ff7849", Other:"#a78bfa", Income:"#00ff9d" };
const fmt = n => `₹${Number(n || 0).toLocaleString("en-IN")}`;
const now = new Date();

export default function Transactions() {
  const [txns, setTxns]       = useState([]);
  const [loading, setLoading] = useState(true);
  const [filter, setFilter]   = useState({ type: "", category: "", month: now.getMonth() + 1, year: now.getFullYear() });
  const [showAdd, setShowAdd] = useState(false);
  const [form, setForm]       = useState({ description: "", amount: "", category: "Food", type: "expense", date: now.toISOString().split("T")[0] });
  const [saving, setSaving]   = useState(false);
  const [msg, setMsg]         = useState("");

  const load = () => {
    setLoading(true);
    const params = {};
    if (filter.type)     params.type     = filter.type;
    if (filter.category) params.category = filter.category;
    if (filter.month)    params.month    = filter.month;
    if (filter.year)     params.year     = filter.year;
    getTransactions(params)
      .then(r => setTxns(r.data))
      .finally(() => setLoading(false));
  };

  useEffect(() => { load(); }, [filter]);

  const del = async (id) => {
    if (!window.confirm("Delete this transaction?")) return;
    await deleteTransaction(id);
    load();
  };

  const add = async () => {
    if (!form.description || !form.amount) return;
    setSaving(true);
    try {
      await createTransaction({ ...form, amount: parseFloat(form.amount), date: new Date(form.date).toISOString() });
      setMsg("✅ Added!"); setForm(f => ({ ...f, description: "", amount: "" }));
      setShowAdd(false); load();
    } catch (e) { setMsg("❌ " + (e.response?.data?.detail || "Error")); }
    setSaving(false);
  };

  const s = {
    page: { animation: "fadeIn 0.3s ease" },
    header: { display: "flex", justifyContent: "space-between", alignItems: "flex-start", marginBottom: 24 },
    title: { fontSize: 26, fontWeight: 800, letterSpacing: "-0.5px" },
    addBtn: { background: `linear-gradient(135deg, ${G.accent}cc, ${G.accent2})`, border: "none", borderRadius: 10, padding: "10px 20px", color: "#fff", fontWeight: 700, fontSize: 13, cursor: "pointer", fontFamily: G.font },
    filters: { display: "flex", gap: 10, marginBottom: 18, flexWrap: "wrap" },
    select: { background: G.surface, border: `1px solid ${G.border}`, borderRadius: 8, padding: "8px 12px", color: G.text, fontSize: 13, fontFamily: G.font, cursor: "pointer" },
    input: { background: `${G.border}50`, border: `1px solid ${G.border}`, borderRadius: 8, padding: "9px 12px", color: G.text, fontSize: 13, fontFamily: G.font, width: "100%" },
    table: { width: "100%", borderCollapse: "collapse" },
    th: { padding: "10px 14px", textAlign: "left", color: G.muted, fontSize: 11, letterSpacing: 1.5, textTransform: "uppercase", fontWeight: 600, borderBottom: `1px solid ${G.border}` },
    td: { padding: "14px", borderBottom: `1px solid ${G.border}18`, fontSize: 13, verticalAlign: "middle" },
    badge: (c) => ({ background: `${c}18`, color: c, border: `1px solid ${c}35`, padding: "3px 10px", borderRadius: 20, fontSize: 11, fontWeight: 600 }),
    card: { background: G.surface, border: `1px solid ${G.border}`, borderRadius: 14, overflow: "hidden" },
    formCard: { background: G.surface, border: `1px solid ${G.border}`, borderRadius: 14, padding: 22, marginBottom: 16 },
    delBtn: { background: `${G.red}15`, border: `1px solid ${G.red}30`, borderRadius: 6, color: G.red, padding: "4px 10px", cursor: "pointer", fontSize: 12, fontFamily: G.font },
  };

  return (
    <div style={s.page}>
      <div style={s.header}>
        <div>
          <div style={s.title}>Transactions</div>
          <div style={{ color: G.muted, fontSize: 13, marginTop: 2 }}>{txns.length} records</div>
        </div>
        <button style={s.addBtn} onClick={() => setShowAdd(v => !v)}>
          {showAdd ? "✕ Cancel" : "+ Add Transaction"}
        </button>
      </div>

      {/* Add form */}
      {showAdd && (
        <div style={s.formCard} className="fade-in">
          <div style={{ fontSize: 13, fontWeight: 700, marginBottom: 14, color: G.accent }}>New Transaction</div>
          <div style={{ display: "grid", gridTemplateColumns: "2fr 1fr 1fr 1fr 1fr", gap: 10, marginBottom: 12 }}>
            {[["Description","text","description","e.g. Lunch"], ["Amount ₹","number","amount","0"]].map(([label, type, key, ph]) => (
              <div key={key}>
                <div style={{ fontSize: 11, color: G.muted, marginBottom: 5, letterSpacing: 1, textTransform: "uppercase" }}>{label}</div>
                <input style={s.input} type={type} placeholder={ph} value={form[key]} onChange={e => setForm(f => ({ ...f, [key]: e.target.value }))} />
              </div>
            ))}
            <div>
              <div style={{ fontSize: 11, color: G.muted, marginBottom: 5, letterSpacing: 1, textTransform: "uppercase" }}>Category</div>
              <select style={s.select} value={form.category} onChange={e => setForm(f => ({ ...f, category: e.target.value }))}>
                {CATEGORIES.map(c => <option key={c}>{c}</option>)}
              </select>
            </div>
            <div>
              <div style={{ fontSize: 11, color: G.muted, marginBottom: 5, letterSpacing: 1, textTransform: "uppercase" }}>Type</div>
              <select style={s.select} value={form.type} onChange={e => setForm(f => ({ ...f, type: e.target.value }))}>
                <option value="expense">Expense</option>
                <option value="income">Income</option>
              </select>
            </div>
            <div>
              <div style={{ fontSize: 11, color: G.muted, marginBottom: 5, letterSpacing: 1, textTransform: "uppercase" }}>Date</div>
              <input style={s.input} type="date" value={form.date} onChange={e => setForm(f => ({ ...f, date: e.target.value }))} />
            </div>
          </div>
          <div style={{ display: "flex", alignItems: "center", gap: 12 }}>
            <button style={s.addBtn} onClick={add} disabled={saving}>{saving ? "Saving..." : "Save Transaction"}</button>
            {msg && <span style={{ fontSize: 13, color: msg.startsWith("✅") ? G.green : G.red }}>{msg}</span>}
          </div>
        </div>
      )}

      {/* Filters */}
      <div style={s.filters}>
        <select style={s.select} value={filter.type} onChange={e => setFilter(f => ({ ...f, type: e.target.value }))}>
          <option value="">All Types</option>
          <option value="expense">Expense</option>
          <option value="income">Income</option>
        </select>
        <select style={s.select} value={filter.category} onChange={e => setFilter(f => ({ ...f, category: e.target.value }))}>
          <option value="">All Categories</option>
          {CATEGORIES.map(c => <option key={c}>{c}</option>)}
        </select>
        <select style={s.select} value={filter.month} onChange={e => setFilter(f => ({ ...f, month: e.target.value }))}>
          {Array.from({ length: 12 }, (_, i) => (
            <option key={i+1} value={i+1}>{new Date(2024, i).toLocaleString("default", { month: "long" })}</option>
          ))}
        </select>
        <select style={s.select} value={filter.year} onChange={e => setFilter(f => ({ ...f, year: e.target.value }))}>
          {[2023, 2024, 2025, 2026].map(y => <option key={y} value={y}>{y}</option>)}
        </select>
      </div>

      {/* Table */}
      <div style={s.card}>
        {loading
          ? <div style={{ padding: 40, textAlign: "center", color: G.muted, fontSize: 13 }}>Loading...</div>
          : txns.length === 0
            ? <div style={{ padding: 40, textAlign: "center", color: G.muted, fontSize: 13 }}>No transactions found. Add your first one above!</div>
            : <table style={s.table}>
                <thead>
                  <tr>
                    {["Date","Description","Category","Type","Amount",""].map(h => (
                      <th key={h} style={s.th}>{h}</th>
                    ))}
                  </tr>
                </thead>
                <tbody>
                  {txns.map(t => (
                    <tr key={t.id} style={{ transition: "background 0.1s" }}
                      onMouseEnter={e => e.currentTarget.style.background = `${G.border}30`}
                      onMouseLeave={e => e.currentTarget.style.background = "transparent"}>
                      <td style={{ ...s.td, color: G.muted, fontFamily: G.mono, fontSize: 12 }}>{t.date.split("T")[0]}</td>
                      <td style={{ ...s.td, fontWeight: 500 }}>{t.description || "—"}</td>
                      <td style={s.td}>
                        <span style={s.badge(CAT_COLORS[t.category] || G.muted)}>{t.category}</span>
                      </td>
                      <td style={s.td}>
                        <span style={s.badge(t.type === "income" ? G.green : G.red)}>{t.type}</span>
                      </td>
                      <td style={{ ...s.td, fontFamily: G.mono, fontWeight: 700, color: t.type === "income" ? G.green : G.text }}>
                        {t.type === "income" ? "+" : "−"}{fmt(t.amount)}
                      </td>
                      <td style={s.td}>
                        <button style={s.delBtn} onClick={() => del(t.id)}>Delete</button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
        }
      </div>
    </div>
  );
}
